from pathlib import Path
import json,re
copy={"en":["Media processing stays on your device. No analytics are enabled. Livestream sends your selected screen and audio to the destination you start. Sharing opens the Android chooser.","Speech models can be downloaded or imported. Transcription stays on your device. Support reports include only your text, selected attachment and device details you enable."],"vi":["Ảnh và video được xử lý trên thiết bị. Không bật phân tích sử dụng. Phát trực tiếp gửi màn hình và âm thanh đã chọn đến đích do bạn khởi chạy. Chia sẻ mở trình chọn của Android.","Bạn có thể tải hoặc nhập model giọng nói. Nhận dạng được thực hiện trên thiết bị. Báo cáo hỗ trợ chỉ gồm nội dung bạn viết, tệp đính kèm đã chọn và thông tin thiết bị mà bạn cho phép."],"de":["Medien werden auf deinem Gerät verarbeitet. Es werden keine Nutzungsanalysen aktiviert. Livestreams senden den ausgewählten Bildschirm und Ton an das von dir gestartete Ziel. Teilen öffnet die Android-Auswahl.","Sprachmodelle können heruntergeladen oder importiert werden. Die Transkription erfolgt auf deinem Gerät. Supportberichte enthalten nur deinen Text, ausgewählte Anhänge und von dir freigegebene Gerätedaten."],"es":["Los archivos se procesan en tu dispositivo. No se activan análisis de uso. La transmisión en directo envía la pantalla y el audio seleccionados al destino que inicias. Compartir abre el selector de Android.","Puedes descargar o importar modelos de voz. La transcripción se realiza en tu dispositivo. Los informes de soporte solo incluyen tu texto, el archivo adjunto seleccionado y los datos del dispositivo que autorices."],"fr":["Les médias sont traités sur votre appareil. Aucune analyse d’utilisation n’est activée. Le direct envoie l’écran et l’audio sélectionnés vers la destination que vous démarrez. Partager ouvre le sélecteur Android.","Les modèles vocaux peuvent être téléchargés ou importés. La transcription reste sur votre appareil. Les rapports d’assistance incluent uniquement votre texte, la pièce jointe choisie et les informations de l’appareil que vous autorisez."],"pt_BR":["A mídia é processada no seu dispositivo. Nenhuma análise de uso é ativada. A transmissão ao vivo envia a tela e o áudio selecionados ao destino que você iniciar. Compartilhar abre o seletor do Android.","Você pode baixar ou importar modelos de voz. A transcrição ocorre no seu dispositivo. Os relatórios de suporte incluem apenas seu texto, o anexo escolhido e os dados do dispositivo que você autorizar."],"id":["Media diproses di perangkat Anda. Analitik penggunaan tidak diaktifkan. Siaran langsung mengirim layar dan audio pilihan Anda ke tujuan yang Anda mulai. Berbagi membuka pemilih Android.","Model suara dapat diunduh atau diimpor. Transkripsi tetap dilakukan di perangkat Anda. Laporan dukungan hanya berisi teks Anda, lampiran pilihan, dan detail perangkat yang Anda izinkan."],"ja":["メディアは端末内で処理され、利用状況の分析は有効になっていません。ライブ配信では、選択した画面と音声が、あなたが配信を開始した送信先へ送られます。共有するとAndroidの共有先選択画面が開きます。","音声モデルはダウンロードまたはインポートできます。文字起こしは端末内で行われます。サポートレポートには、入力した文章、選択した添付ファイル、許可した端末情報のみが含まれます。"],"ko":["미디어는 기기에서 처리되며 사용 분석은 활성화되지 않습니다. 라이브 방송은 선택한 화면과 오디오를 직접 시작한 대상에 전송합니다. 공유하면 Android 공유 대상 선택창이 열립니다.","음성 모델은 다운로드하거나 가져올 수 있습니다. 받아쓰기는 기기에서 처리됩니다. 지원 보고서에는 작성한 글, 선택한 첨부 파일, 허용한 기기 정보만 포함됩니다."],"zh_Hans":["媒体在设备上处理，不启用使用情况分析。直播会将选定的屏幕和音频发送到你主动开始推流的目标。分享会打开 Android 分享选择器。","语音模型可下载或导入。转写在设备上进行。支持报告只包含你填写的文字、选定的附件和主动允许提供的设备信息。"],"ar":["تُعالج الوسائط على جهازك، ولا تُفعّل تحليلات الاستخدام. يرسل البث المباشر الشاشة والصوت المحددين إلى الوجهة التي تبدأ البث إليها. تفتح المشاركة أداة اختيار Android.","يمكن تنزيل نماذج الكلام أو استيرادها. يجري التفريغ النصي على جهازك. تتضمن تقارير الدعم نصك والمرفق المحدد وتفاصيل الجهاز التي تسمح بها فقط."],"hi":["मीडिया आपके डिवाइस पर संसाधित होता है। उपयोग विश्लेषण सक्षम नहीं है। लाइव प्रसारण चुनी गई स्क्रीन और ऑडियो को उसी गंतव्य पर भेजता है जिसे आप शुरू करते हैं। साझा करने पर Android का चयनकर्ता खुलता है।","वाक् मॉडल डाउनलोड या आयात किए जा सकते हैं। प्रतिलेखन डिवाइस पर ही होता है। सहायता रिपोर्ट में केवल आपका लिखा पाठ, चुना गया अटैचमेंट और आपकी अनुमति वाली डिवाइस जानकारी शामिल होती है।"],"pt":["A mídia é processada no seu dispositivo. Nenhuma análise de uso é ativada. A transmissão ao vivo envia a tela e o áudio selecionados ao destino que você iniciar. Compartilhar abre o seletor do Android.","Você pode baixar ou importar modelos de voz. A transcrição ocorre no seu dispositivo. Os relatórios de suporte incluem apenas seu texto, o anexo escolhido e os dados do dispositivo que você autorizar."],"zh":["媒体在设备上处理，不启用使用情况分析。直播会将选定的屏幕和音频发送到你主动开始推流的目标。分享会打开 Android 分享选择器。","语音模型可下载或导入。转写在设备上进行。支持报告只包含你填写的文字、选定的附件和主动允许提供的设备信息。"]}
for locale,(short,extra) in copy.items():
 p=Path('lib/l10n/app_'+locale+'.arb')
 s=p.read_text(encoding='utf8')
 for key,value in [('mediaProcessingStaysOnYourDeviceNo',short),('captureEditingDraftsAndExportsRunLocally',short+' '+extra)]:
  s,n=re.subn('('+re.escape(json.dumps(key))+r': )\"[^\"\n]*\"',lambda m:m.group(1)+json.dumps(value,ensure_ascii=False),s)
  assert n==1,(locale,key)
 p.write_text(s,encoding='utf8')
print('Updated existing privacy keys to disclose explicit livestream; human language review remains pending.')
